"""Money helpers.

Historically everything in this package used raw floats. A Decimal-based
``Money`` value type is being introduced; every module in the money path now
uses it.
"""

from __future__ import annotations

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

#: Two-decimal-place quantum used by every monetary rounding operation.
CENTS = Decimal("0.01")

#: Single shared tax rate. Every module that needs "the" tax rate imports this
#: object (rather than redefining its own float literal) so there is exactly
#: one source of truth.
TAX_RATE = Decimal("0.0825")


def quantize(amount: Decimal) -> Decimal:
    """Round ``amount`` to two decimal places using ROUND_HALF_UP."""
    return amount.quantize(CENTS, rounding=ROUND_HALF_UP)


@dataclass(frozen=True)
class Money:
    amount: Decimal
    currency: str = "USD"

    def __post_init__(self) -> None:
        if not isinstance(self.amount, Decimal):
            raise TypeError("Money.amount must be a Decimal")

    def __add__(self, other: "Money") -> "Money":
        self._check(other)
        return Money(self.amount + other.amount, self.currency)

    def __sub__(self, other: "Money") -> "Money":
        self._check(other)
        return Money(self.amount - other.amount, self.currency)

    def _check(self, other: "Money") -> None:
        if other.currency != self.currency:
            raise ValueError(f"currency mismatch: {self.currency} vs {other.currency}")

    def __str__(self) -> str:
        return f"{self.amount} {self.currency}"

    def to_float(self) -> float:
        """Escape hatch for legacy callers that still require a plain float."""
        return float(self.amount)

