"""Shopping cart totals. Shares the tax rules found in invoice.py via ``money.TAX_RATE``."""

from __future__ import annotations

from dataclasses import dataclass, field
from decimal import Decimal

from . import catalog
from .money import Money, TAX_RATE, quantize

__all__ = ["TAX_RATE", "Line", "Cart"]


@dataclass
class Line:
    sku: str
    quantity: int


@dataclass
class Cart:
    lines: list[Line] = field(default_factory=list)

    def add(self, sku: str, quantity: int = 1) -> None:
        self.lines.append(Line(sku, quantity))

    def subtotal(self) -> Money:
        total = Decimal("0")
        for line in self.lines:
            total += catalog.lookup(line.sku).unit_price * line.quantity
        return Money(quantize(total))

    def tax(self) -> Money:
        taxed = Decimal("0")
        for line in self.lines:
            product = catalog.lookup(line.sku)
            if product.taxable:
                taxed += product.unit_price * line.quantity
        return Money(quantize(taxed * TAX_RATE))

    def total(self) -> Money:
        return Money(quantize(self.subtotal().amount + self.tax().amount))

