"""Discount rules.

``percentage_off`` sits on the money path (invoices apply it to line
amounts) so it is Decimal-based and quantized like everything else. The
bulk-rule helpers stay float-based: they return a *percentage number*, not
money, and ``tests/test_smoke.py`` pins their existing float behaviour.
"""

from __future__ import annotations

from decimal import Decimal

from .money import quantize


def percentage_off(amount: Decimal, percent: Decimal) -> Decimal:
    return quantize(amount * (Decimal("1") - percent / Decimal("100")))


def flat_off(amount: Decimal, discount: Decimal) -> Decimal:
    return quantize(max(amount - discount, Decimal("0")))


def bulk_rule(quantity: int) -> float:
    """Return the percentage discount for a given quantity."""
    if quantity >= 100:
        return 15.0
    if quantity >= 25:
        return 7.5
    if quantity >= 10:
        return 2.5
    return 0.0

