"""Legacy helpers kept for the old storefront. Still float-only externally.

Callers outside this repository import ``legacy_total``; its *signature* must
not change (it still returns a plain ``float``), but internally it now uses
the Decimal-based ``Cart`` and only converts to ``float`` at the boundary.
"""

from __future__ import annotations

from . import cart


def legacy_total(items: list[tuple[str, int]]) -> float:
    basket = cart.Cart()
    for sku, quantity in items:
        basket.add(sku, quantity)
    return basket.total().to_float()


def legacy_tax_only(items: list[tuple[str, int]]) -> float:
    basket = cart.Cart()
    for sku, quantity in items:
        basket.add(sku, quantity)
    return basket.tax().to_float()

